            var g = ac.createGain(); g.gain.setValueAtTime(0.08, ac.currentTime); g.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + 0.15);
            src.connect(filt); filt.connect(g); g.connect(ac.destination); src.start();
