        (function() {
          var ac = getAudioCtx(); if (!ac) return;
          try {
            var bufSize = Math.floor(ac.sampleRate * 0.06);
            var buf = ac.createBuffer(1, bufSize, ac.sampleRate);
            var data = buf.getChannelData(0);
            for (var i = 0; i < bufSize; i++) data[i] = (Math.random() * 2 - 1) * 0.5;
